$nodeScript = @'
const fs = require('fs')
const { PNG } = require('pngjs')
const pixelmatch = require('pixelmatch')
const actual = PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/artifacts/task2468-navbar-visual/navbar-visual-1920.png'))
const reference = PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/home-v2/fixtures/navbar-reference.png'))
const h = actual.height
const crop = (img, x, width) => {
  const data = Buffer.alloc(width * h * 4)
  for (let y = 0; y < h; y++) img.data.copy(data, y * width * 4, (y * img.width + x) * 4, (y * img.width + x + width) * 4)
  return data
}
for (const [name, x, width] of [['brand', 0, 400], ['active+first', 400, 240], ['nav-middle', 640, 1040], ['arrow', 1680, 42], ['gap', 1722, 112], ['user', 1834, 86]]) {
  const count = pixelmatch(crop(actual, x, width), crop(reference, x, width), null, width, h, { threshold: 0.1 })
  console.log(`${name}: ${count}/${width * h} mismatched (${(100 * (1 - count / (width * h))).toFixed(2)}% similar)`)
}
'@
node -e $nodeScript
